import{_ as e,o,c as a,ag as r}from"./chunks/framework.4s5LDCII.js";const _=JSON.parse('{"title":"行动清单：可执行内容以逐条溯源为前提","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0010-actionable-excerpts.md","filePath":"project/adr/0010-actionable-excerpts.md"}'),i={name:"project/adr/0010-actionable-excerpts.md"};function l(c,t,d,n,s,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="行动清单-可执行内容以逐条溯源为前提" tabindex="-1">行动清单：可执行内容以逐条溯源为前提 <a class="header-anchor" href="#行动清单-可执行内容以逐条溯源为前提" aria-label="Permalink to &quot;行动清单：可执行内容以逐条溯源为前提&quot;">​</a></h1><p>用户希望词条从&quot;地图式导读&quot;升级为可直接执行的整理（提取、概括、给出可实行的办法，不满意的用户再去原文核对）。为守住&quot;不生产医疗科普&quot;的合规红线（ADR 0004、0006，2025 年网信办《关于规范&quot;自媒体&quot;医疗科普行为的通知》），确定如下边界：</p><ol><li>行动清单的每一条都必须能在官方原文中找到对应原句或数字，并标注出处章节；语言可以口语化，数字与结论不得改动，不跨文件组合。</li><li>唯一例外是显式标注的「本站提示」，仅限中性工具性内容（量具使用、看标签方法等），永不涉及医学判断。</li><li>生产流水线：pdftotext 提取官方 PDF 全文 → AI 结构化整理 → 人工逐条对照原文核验，<code>reviewed</code> 字段控制发布状态。</li><li>免责声明同步升级：&quot;本页所有建议均整理自官方文件原文、逐条可溯源；本站不构成诊疗建议，与医生的治疗方案冲突时，以医嘱为准。&quot;</li></ol><p>词条新结构：速览卡 → 行动清单（买/做/吃/动/测）→ 常见误区（仅原文有对应告诫时）→ 分地区食谱指引 → 原文链接与溯源。</p><h2 id="修订-上线后用户反馈" tabindex="-1">修订（上线后用户反馈） <a class="header-anchor" href="#修订-上线后用户反馈" aria-label="Permalink to &quot;修订（上线后用户反馈）&quot;">​</a></h2><ul><li><strong>发文字号字段整体取消</strong>：用户核验时&quot;找不到出处&quot;——转述而来的字号无法自证，且原文页自带该信息。本站不再转述任何无法被用户直接核验的字段。</li><li><strong>出处一律改为跳转链接</strong>：官方 PDF 托管为本站镜像（<code>web/public/guides-pdf/</code>，政府公文属公共领域），行动清单/速览卡的&quot;出处&quot;是 <code>#page=N</code> 直达原文对应页的链接；纯文字章节号（如&quot;三(一)&quot;）因用户无法定位而废弃。页码由 PyMuPDF 在提取时计算。</li></ul>',6)])])}const q=e(i,[["render",l]]);export{_ as __pageData,q as default};
